import { GoogleGenAI } from "@google/genai";
import { MENU_ITEMS, BILLO_INFO } from "../constants";

export interface ChatMessage {
  role: 'user' | 'model';
  parts: { text: string }[];
}

/**
 * Service Khady IA - Expert en gastronomie nigérienne
 */
export const getSmartResponse = async (userMessage: string, history: ChatMessage[] = []): Promise<string> => {
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    return "Salam ! Je suis en pleine préparation en cuisine. En attendant, nos plats sont disponibles à la commande ! 😊";
  }

  try {
    const ai = new GoogleGenAI({ apiKey });

    const systemInstruction = `
      Tu es "Khady IA", l'assistante virtuelle de "Khady's Food & Event" à Niamey.
      TON STYLE: Chaleureux, poli, utilisant "Salam", "Barka" ou "Fofo".
      TES CONNAISSANCES:
      - Lieu: Quartier Plateau, Niamey.
      - Menu: ${MENU_ITEMS.map(i => `${i.name} (${i.price} CFA)`).join(', ')}.
      - Livraison: Via ${BILLO_INFO.name}. 1000F-1500F centre, 2000F-2500F périphérie.
      - Pause prière: Vendredi 12h-15h.
      CONSIGNES: Sois concise et encourage la commande. Si le client veut un plat épicé, suggère le Tiep.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [...history, { role: 'user', parts: [{ text: userMessage }] }],
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7,
        topP: 0.95,
      },
    });

    return response.text || "Barka ! Je n'ai pas bien entendu, pouvez-vous répéter ?";

  } catch (error) {
    console.error("Gemini Error:", error);
    return "Fofo ! Une petite coupure réseau à Niamey, mais je suis toujours là. Que puis-je pour vous ?";
  }
};

