import { GoogleGenAI } from "@google/genai";
import { MENU_ITEMS, BILLO_INFO } from "../constants";

export interface ChatMessage {
  role: 'user' | 'model';
  parts: { text: string }[];
}

/**
 * Khady IA - L'intelligence culinaire au service de Niamey
 */
export const getSmartResponse = async (userMessage: string, history: ChatMessage[] = []): Promise<string> => {
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    return "Salam ! Je prépare actuellement mes épices. En attendant, n'hésitez pas à consulter notre menu premium ! 🥘";
  }

  try {
    const ai = new GoogleGenAI({ apiKey });

    const systemInstruction = `
      Tu es "Khady IA", l'ambassadrice de "Khady's Food & Event" à Niamey.
      TON TON : Très poli, chaleureux, typiquement nigérien (utilise Salam, Barka, Fofo).
      TES MISSIONS :
      1. Guider les clients dans le menu : ${MENU_ITEMS.map(i => `${i.name} (${i.price} F)`).join(', ')}.
      2. Expliquer la livraison : Partenaire ${BILLO_INFO.name}, tarifs 1000F-2500F selon zone.
      3. Service Traiteur : Pour mariages, baptêmes et événements pro.
      CONSIGNE : Sois concise (max 3 phrases). Si on te parle de Tiep, vante la qualité de notre poisson.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [...history, { role: 'user', parts: [{ text: userMessage }] }],
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.8,
        topP: 0.9,
      },
    });

    return response.text || "Barka ! Je n'ai pas bien saisi, pouvez-vous reformuler ?";

  } catch (error) {
    console.error("Gemini Error:", error);
    return "Fofo ! Une petite perturbation sur le réseau, mais Khady IA est toujours là pour vous servir !";
  }
};

